<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)$_SESSION['role'];$uid=(int)$_SESSION['user_id'];$manager=in_array($role,['admin','director','sub_director','headteacher'],true);$staffRoles=['admin','director','sub_director','headteacher','head_academic','assistant_academic','examination_officer','teacher'];$guardian=in_array($role,['parent','pupil'],true);if(!$guardian&&!in_array($role,$staffRoles,true)){http_response_code(403);exit('Your role cannot access report cards.');}$db=db();$school=0;$pupilId=(int)($_GET['pupil_id']??0);$pupil=null;$schools=[];$periods=[];$card=null;$results=[];
if($role==='parent'){$q=$db->prepare("SELECT p.id,p.school_id,p.first_name,p.middle_name,p.last_name,p.admission_number,p.class_level,p.stream,s.name school_name FROM pupil_guardians g JOIN pupils p ON p.id=g.pupil_id AND p.school_id=g.school_id JOIN schools s ON s.id=p.school_id WHERE g.guardian_user_id=? AND p.id=? AND p.status='active'");$q->execute([$uid,$pupilId]);$pupil=$q->fetch();if(!$pupil){http_response_code(404);exit('Linked active pupil not found.');}$school=(int)$pupil['school_id'];}
elseif($role==='pupil'){$q=$db->prepare("SELECT p.id,p.school_id,p.first_name,p.middle_name,p.last_name,p.admission_number,p.class_level,p.stream,s.name school_name FROM pupil_accounts a JOIN pupils p ON p.id=a.pupil_id AND p.school_id=a.school_id JOIN schools s ON s.id=p.school_id WHERE a.user_id=? AND a.active=1 AND p.status='active' LIMIT 1");$q->execute([$uid]);$pupil=$q->fetch();if(!$pupil){http_response_code(403);exit('No active pupil account is linked.');}$pupilId=(int)$pupil['id'];$school=(int)$pupil['school_id'];}
else{$q=$db->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$schoolIds=array_map('intval',array_column($schools,'id'));if(!$schoolIds){http_response_code(403);exit('No school is linked to your account.');}$school=(int)($_GET['school_id']??$schoolIds[0]);if(!in_array($school,$schoolIds,true)){http_response_code(403);exit('That school is outside your access.');}$scope='';$params=[$school];if($role==='teacher'||in_array($role,['assistant_academic','head_academic','examination_officer'],true)){$scope=" AND (EXISTS(SELECT 1 FROM teacher_assignments a WHERE a.user_id=? AND a.school_id=r.school_id AND a.active=1 AND a.class_level=r.class_level AND a.subject=r.subject) OR EXISTS(SELECT 1 FROM result_delegations d WHERE d.user_id=? AND d.school_id=r.school_id AND d.active=1 AND d.academic_year=r.academic_year AND (d.class_level IS NULL OR d.class_level=r.class_level)))";$params[]=$uid;$params[]=$uid;}$q=$db->prepare("SELECT DISTINCT p.id,p.school_id,p.first_name,p.middle_name,p.last_name,p.admission_number,p.class_level,p.stream,s.name school_name FROM pupils p JOIN schools s ON s.id=p.school_id JOIN pupil_results r ON r.pupil_id=p.id AND r.school_id=p.school_id JOIN school_exams x ON x.school_id=r.school_id AND x.name=r.exam_name AND x.academic_year=r.academic_year AND x.status='results_published' AND (x.class_id IS NULL OR x.class_id IN (SELECT c.id FROM school_classes c WHERE c.school_id=r.school_id AND c.name=r.class_level)) AND (x.subject_id IS NULL OR x.subject_id IN (SELECT cs.id FROM school_class_subjects cs JOIN school_classes c ON c.id=cs.class_id WHERE c.school_id=r.school_id AND c.name=r.class_level AND cs.name=r.subject)) WHERE p.school_id=?$scope ORDER BY p.class_level,p.last_name,p.first_name");$q->execute($params);$pupils=$q->fetchAll();$pupil=null;foreach($pupils as $candidate)if((int)$candidate['id']===$pupilId){$pupil=$candidate;break;}if($pupilId&&!$pupil){http_response_code(403);exit('Pupil is outside your published-results scope.');}if(!$pupil&&$pupils){$pupil=$pupils[0];$pupilId=(int)$pupil['id'];}}
if($pupil){$school=(int)$pupil['school_id'];$q=$db->prepare("SELECT DISTINCT x.academic_year,COALESCE(x.term,'') term FROM pupil_results r JOIN school_exams x ON x.school_id=r.school_id AND x.name=r.exam_name AND x.academic_year=r.academic_year AND x.status='results_published' AND (x.class_id IS NULL OR x.class_id IN (SELECT c.id FROM school_classes c WHERE c.school_id=r.school_id AND c.name=r.class_level)) AND (x.subject_id IS NULL OR x.subject_id IN (SELECT cs.id FROM school_class_subjects cs JOIN school_classes c ON c.id=cs.class_id WHERE c.school_id=r.school_id AND c.name=r.class_level AND cs.name=r.subject)) WHERE r.school_id=? AND r.pupil_id=? ORDER BY x.academic_year DESC,x.term DESC");$q->execute([$school,$pupilId]);$periods=$q->fetchAll();$availableYears=array_values(array_unique(array_map(fn($x)=>(int)$x['academic_year'],$periods)));$year=(int)($_GET['academic_year']??($availableYears[0]??0));$availableTerms=array_values(array_unique(array_map(fn($x)=>(string)$x['term'],array_filter($periods,fn($x)=>(int)$x['academic_year']===$year))));$term=(string)($_GET['term']??($availableTerms[0]??''));if($guardian&&!empty($_GET['period'])&&str_contains((string)$_GET['period'],'::')){[$periodYear,$periodTerm]=explode('::',(string)$_GET['period'],2);$year=(int)$periodYear;$term=$periodTerm;$availableTerms=array_values(array_unique(array_map(fn($x)=>(string)$x['term'],array_filter($periods,fn($x)=>(int)$x['academic_year']===$year))));}if($year&&in_array($year,$availableYears,true)&&in_array($term,$availableTerms,true)){$q=$db->prepare("SELECT r.exam_name,r.assessment,r.class_level,r.stream,r.subject,r.score,r.max_score,r.updated_at,(SELECT c.id FROM school_classes c WHERE c.school_id=r.school_id AND c.name=r.class_level LIMIT 1) class_id FROM pupil_results r JOIN school_exams x ON x.school_id=r.school_id AND x.name=r.exam_name AND x.academic_year=r.academic_year AND x.status='results_published' AND (x.class_id IS NULL OR x.class_id IN (SELECT c.id FROM school_classes c WHERE c.school_id=r.school_id AND c.name=r.class_level)) AND (x.subject_id IS NULL OR x.subject_id IN (SELECT cs.id FROM school_class_subjects cs JOIN school_classes c ON c.id=cs.class_id WHERE c.school_id=r.school_id AND c.name=r.class_level AND cs.name=r.subject)) WHERE r.school_id=? AND r.pupil_id=? AND r.academic_year=? AND COALESCE(x.term,'')=? ORDER BY r.subject,x.exam_date,x.name,r.assessment");$q->execute([$school,$pupilId,$year,$term]);$results=$q->fetchAll();$gradeBandsByClass=[];foreach(array_unique(array_filter(array_map('intval',array_column($results,'class_id')))) as $classId){$gq=$db->prepare("SELECT id FROM school_grading_scales WHERE school_id=? AND academic_year=? AND status='published' AND (class_id=? OR class_id IS NULL) ORDER BY (class_id IS NULL),published_at DESC,id DESC LIMIT 1");$gq->execute([$school,(int)$year,$classId]);$scaleId=(int)($gq->fetchColumn()?:0);$gradeBandsByClass[$classId]=[];if($scaleId){$gq=$db->prepare('SELECT label,minimum_percent,maximum_percent FROM school_grading_bands WHERE scale_id=? ORDER BY minimum_percent');$gq->execute([$scaleId]);$gradeBandsByClass[$classId]=$gq->fetchAll();}}foreach($results as &$result){$result['normalized_percent']=round((float)$result['max_score']>0?100*(float)$result['score']/(float)$result['max_score']:0,2);$result['grade']='Ungraded';foreach($gradeBandsByClass[(int)$result['class_id']]??[] as $band)if($result['normalized_percent']>=(float)$band['minimum_percent']&&$result['normalized_percent']<=(float)$band['maximum_percent']){$result['grade']=$band['label'];break;}}unset($result);$q=$db->prepare('SELECT * FROM pupil_report_cards WHERE school_id=? AND pupil_id=? AND academic_year=? AND term=?'.($guardian?" AND status='published'":''));$q->execute([$school,$pupilId,$year,$term]);$card=$q->fetch()?:null;}}
$isStaff=!$guardian;$year=(int)($_GET['academic_year']??($periods[0]['academic_year']??0));$term=(string)($_GET['term']??($periods[0]['term']??''));$commentRoles=['teacher','assistant_academic','head_academic','examination_officer'];$canTeacherComment=$isStaff&&($manager||in_array($role,$commentRoles,true));$schoolName=$pupil['school_name']??'School';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Report card · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><style>@media print{.sidebar,.topbar,.report-card-controls,.comment-editor,.page-footer{display:none!important}.app-shell,.main-area,.page-content{display:block!important;margin:0!important;padding:0!important;max-width:none!important}.content-section{break-inside:avoid;box-shadow:none!important}}</style><script defer src="assets/app.js"></script><script defer src="assets/report-cards.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Report card</div><div class="top-actions"><span class="role-chip"><?=e($guardian?($role==='parent'?'Parent / Guardian':'Pupil / Learner'):str_replace('_',' ',$role))?></span></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">ACADEMIC REPORT</div><h1><?=e(trim(($pupil['first_name']??'').' '.($pupil['middle_name']??'').' '.($pupil['last_name']??'')))?></h1><p class="muted"><?=e($schoolName.' · '.($pupil['class_level']??'').' · '.($pupil['stream']??'').' · '.($pupil['admission_number']??''))?></p></div><button class="button report-card-controls" type="button" onclick="window.print()">Print report card</button><button class="button report-card-controls" type="button" data-report-card-word>Download Word-compatible copy</button></section><?php if($isStaff):?><form method="get" class="note-create report-card-controls" data-report-card-filter><div class="form-grid"><?php if(count($schools)>1):?><div><label for="card-school">School</label><select id="card-school" name="school_id"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><?php else:?><input type="hidden" name="school_id" value="<?=$school?>"><?php endif;?><div><label for="card-pupil">Pupil</label><select id="card-pupil" name="pupil_id"><?php foreach($pupils as $p):?><option value="<?=$p['id']?>"<?=(int)$p['id']===$pupilId?' selected':''?>><?=e($p['class_level'].' · '.$p['first_name'].' '.$p['last_name'].' · '.$p['admission_number'])?></option><?php endforeach;?></select></div><div><label for="card-year">Academic year</label><select id="card-year" name="academic_year"><?php foreach($availableYears??[] as $y):?><option value="<?=$y?>"<?=$year===$y?' selected':''?>><?=$y?></option><?php endforeach;?></select></div><div><label for="card-term">Term</label><select id="card-term" name="term"><?php foreach($availableTerms??[] as $t):?><option value="<?=e($t)?>"<?=$term===$t?' selected':''?>><?=e($t?:'Unspecified term')?></option><?php endforeach;?></select></div></div><button class="button primary" type="submit">View report card</button></form><?php elseif($guardian&&count($periods)>1):?><form method="get" class="report-card-controls" data-report-card-filter><?php if($role==='parent'):?><input type="hidden" name="pupil_id" value="<?=$pupilId?>"><?php endif;?><label for="card-period">Report period</label><select id="card-period" name="period" onchange="this.form.submit()"><?php foreach($periods as $period):$periodKey=$period['academic_year'].'::'.$period['term'];?><option value="<?=e($periodKey)?>"<?=((int)$period['academic_year']===$year&&(string)$period['term']===$term)?' selected':''?>><?=e($period['academic_year'].' · '.($period['term']?:'Unspecified term'))?></option><?php endforeach;?></select></form><?php endif;?><?php if(!$pupil):?><div class="empty-state"><h2>No report records</h2><p>No published results are available in this account’s scope.</p></div><?php elseif(!$year||!in_array($term,$availableTerms??[],true)):?><div class="empty-state"><h2>No report period available</h2><p>A report card needs at least one published result with an academic year and term.</p></div><?php elseif($guardian&&!$card):?><div class="empty-state"><h2>Report card not published</h2><p>Your school has not published a report card for this period.</p></div><?php else:?><section class="content-section"><div class="section-heading"><div><div class="eyebrow"><?=e($year.' · '.$term)?></div><h2>Published academic results</h2><p class="muted">Only published examination scores are included. School-published grade bands apply by class; scores outside configured bands appear as ungraded.</p></div><?php if($card):?><span class="status-badge <?=e($card['status'])?>"><span></span><?=e(ucfirst($card['status']))?></span><?php endif;?></div><?php if($results):?><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Class</th><th>Assessment</th><th>Exam</th><th>Score</th><th>Normalized score</th><th>Grade</th></tr></thead><tbody><?php foreach($results as $result):$pct=(float)$result['max_score']>0?100*(float)$result['score']/(float)$result['max_score']:0;?><tr><td><?=e($result['subject'])?></td><td><?=e($result['class_level'].($result['stream']?' · '.$result['stream']:''))?></td><td><?=e($result['assessment'])?></td><td><?=e($result['exam_name'])?></td><td><?=number_format((float)$result['score'],2)?> / <?=number_format((float)$result['max_score'],2)?></td><td><?=number_format($pct,1)?>%</td><td><?=e($result['grade'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($card&&$card['teacher_comment']):?><section class="question-card"><h3>Teacher comment</h3><p><?=nl2br(e($card['teacher_comment']))?></p></section><?php endif;?><?php if($card&&$card['headteacher_comment']):?><section class="question-card"><h3>Headteacher comment</h3><p><?=nl2br(e($card['headteacher_comment']))?></p></section><?php endif;?></section><?php if($canTeacherComment):?><section class="note-create comment-editor"><div class="section-heading"><div><div class="eyebrow">REPORT COMMENTS</div><h2>Teacher comment</h2></div></div><form method="post" data-report-card-comment><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="pupil_id" value="<?=$pupilId?>"><input type="hidden" name="academic_year" value="<?=$year?>"><input type="hidden" name="term" value="<?=e($term)?>"><input type="hidden" name="action" value="save_comment"><input type="hidden" name="comment_type" value="teacher"><label for="teacher-comment">Teacher comment</label><textarea id="teacher-comment" name="comment" maxlength="4000" rows="4"><?=e($card['teacher_comment']??'')?></textarea><button class="button" type="submit">Save teacher comment</button></form><?php if($manager):?><form method="post" class="comment-editor" data-report-card-comment><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="pupil_id" value="<?=$pupilId?>"><input type="hidden" name="academic_year" value="<?=$year?>"><input type="hidden" name="term" value="<?=e($term)?>"><input type="hidden" name="action" value="save_comment"><input type="hidden" name="comment_type" value="headteacher"><label for="headteacher-comment">Headteacher comment</label><textarea id="headteacher-comment" name="comment" maxlength="4000" rows="4"><?=e($card['headteacher_comment']??'')?></textarea><button class="button" type="submit">Save headteacher comment</button></form><?php if($card&&(empty($card['status'])||$card['status']==='draft')):?><form method="post" class="comment-editor" data-report-card-comment><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="pupil_id" value="<?=$pupilId?>"><input type="hidden" name="academic_year" value="<?=$year?>"><input type="hidden" name="term" value="<?=e($term)?>"><input type="hidden" name="action" value="publish"><input type="hidden" name="report_card_id" value="<?=$card['id']?>"><button class="button primary" type="submit">Publish report card</button></form><?php endif;?><?php endif;?></section><?php endif;?><?php endif;?><footer class="page-footer">ShuleLite <span>·</span> Report cards</footer></div></main></div></body></html>
